import type { PageFlowScanColour } from "../../sdk/models";

/** Scans are taken at 300 dpi, as the scan-and-upload ticket (Redmine 47227) requires. */
export const SCAN_DPI = 300;

export type ScanMode = "single" | "multi";
export type ScanOutput = "pdf" | "jpeg" | "png" | "bmp";

/** How the browser changes the agent's JPEG page before it is saved. */
export type ScanConversion = "none" | "bmp" | "png";

export interface ScanPlan {
  /** Format asked of the agent. A multi-page scan uses JPEG pages, and the agent joins them into a PDF. */
  agentFormat: "pdf" | "jpeg";
  preset: "photo" | "document";
  colour: PageFlowScanColour;
  /** What the browser does to a single JPEG page: nothing, or convert it to BMP or PNG. */
  convertTo: ScanConversion;
  /** True when a single JPEG page must be converted to BMP in the browser. */
  convertToBmp: boolean;
}

/** A BMP, JPEG or PNG holds one page, so a multi-page scan is always a PDF. */
export function effectiveOutput(mode: ScanMode, output: ScanOutput): ScanOutput {
  return mode === "multi" ? "pdf" : output;
}

/** The file extension and MIME type of a saved scan. */
export function outputFileType(output: ScanOutput): { extension: string; mimeType: string } {
  switch (output) {
    case "pdf":
      return { extension: "pdf", mimeType: "application/pdf" };
    case "jpeg":
      return { extension: "jpg", mimeType: "image/jpeg" };
    case "png":
      return { extension: "png", mimeType: "image/png" };
    case "bmp":
      return { extension: "bmp", mimeType: "image/bmp" };
  }
}

function jpegPlan(preset: ScanPlan["preset"], colour: PageFlowScanColour, convertTo: ScanConversion): ScanPlan {
  return { agentFormat: "jpeg", preset, colour, convertTo, convertToBmp: convertTo === "bmp" };
}

export function planScan(
  mode: ScanMode,
  colour: PageFlowScanColour,
  output: ScanOutput,
): ScanPlan {
  const preset = colour === "colour" ? "photo" : "document";
  if (mode === "multi") {
    return jpegPlan(preset, colour, "none");
  }
  switch (effectiveOutput(mode, output)) {
    case "pdf":
      return { agentFormat: "pdf", preset, colour, convertTo: "none", convertToBmp: false };
    case "jpeg":
      return jpegPlan(preset, colour, "none");
    case "png":
      return jpegPlan(preset, colour, "png");
    case "bmp":
      return jpegPlan(preset, colour, "bmp");
  }
}
